#!/usr/bin/env python3
import base64
import os

# Known-good minimal silent MP3 (~0.05s)
silent_mp3_b64 = ''
mp3_data = base64.b64decode(silent_mp3_b64)

os.makedirs('tests/fixtures/uploaded/audio', exist_ok=True)

# Also create audio for all test tracks that try to play
test_keys = [
    'test-playlist.mp3',
    'test-transport.mp3',
    'test-keyboard.mp3',
]

for key in test_keys:
    filepath = os.path.join('tests/fixtures/uploaded/audio', key)
    os.makedirs(os.path.dirname(filepath), exist_ok=True)
    with open(filepath, 'wb') as f:
        f.write(mp3_data)
    print(f'Created {filepath} ({len(mp3_data)} bytes)')

print('Done')
